def f_wrapcol(S):
    n=len(S); out=[r[:] for r in S]
    for i in range(n):
        for j in range(n):
            if out[i][j]!=0: continue
            a,b=i,j-1
            while a<n:
                if b<0: b+=n
                if out[a][b]!=0:
                    out[i][j]=out[a][b]; break
                a+=1; b-=1
    return out
